package io.github.turbopro.ism.qualification;

import io.github.turbopro.ism.common.infrastructure.tenant.TenantScopedMapper;
import org.apache.ibatis.annotations.*;
import java.util.List;

@Mapper
public interface PortalCertificateSubmissionMapper extends TenantScopedMapper {
    @Select("SELECT p.account_id,q.status,q.version FROM qua_portal_submission p JOIN qua_supplier_qualification q ON q.id=p.qualification_id AND q.tenant_id=p.tenant_id WHERE p.tenant_id=#{tenantId} AND p.supplier_id=#{supplierId} AND q.id=#{id} FOR UPDATE")
    PortalCertificateSubmissionModels.WithdrawalTarget lockWithdrawalTarget(long tenantId,long supplierId,long id);
    @Select("SELECT account_id,source_version,reason FROM qua_portal_withdrawal WHERE tenant_id=#{tenantId} AND qualification_id=#{id} FOR UPDATE")
    PortalCertificateSubmissionModels.Withdrawal withdrawal(long tenantId,long id);
    @Update("UPDATE qua_supplier_qualification SET status='WITHDRAWN',version=version+1,updated_by=#{accountId} WHERE tenant_id=#{tenantId} AND supplier_id=#{supplierId} AND id=#{id} AND status='DRAFT' AND version=#{version}")
    int withdraw(long tenantId,long supplierId,long id,long accountId,int version);
    @Insert("INSERT INTO qua_portal_withdrawal(qualification_id,tenant_id,supplier_id,account_id,source_version,reason) VALUES(#{id},#{tenantId},#{supplierId},#{accountId},#{version},#{reason})")
    int recordWithdrawal(long tenantId,long supplierId,long id,long accountId,int version,String reason);
    @Select("SELECT qualification_id,account_id,request_json,request_key,file_name,created_at FROM qua_portal_submission WHERE tenant_id=#{tenantId} AND supplier_id=#{supplierId} AND request_key=#{key} FOR UPDATE")
    PortalCertificateSubmissionModels.Row byKey(long tenantId,long supplierId,String key);
    @Insert("INSERT INTO qua_portal_submission(qualification_id,tenant_id,supplier_id,account_id,request_key,upload_id,request_json,file_name) VALUES(#{id},#{tenantId},#{supplierId},#{accountId},#{key},#{uploadId},#{request},#{fileName})")
    int insert(long id,long tenantId,long supplierId,long accountId,String key,long uploadId,String request,String fileName);
    @Insert("INSERT INTO qua_portal_renewal(qualification_id,tenant_id,supplier_id,parent_id,parent_version) VALUES(#{id},#{tenantId},#{supplierId},#{parentId},#{version})")
    int insertRenewal(long id,long tenantId,long supplierId,long parentId,int version);
    @Select("SELECT q.id,q.qualification_type_id type_id,q.status,q.version,COALESCE(c.root_id,q.id) root_id,COALESCE(c.round_no,0) round_no,r.parent_id renewal_parent_id,r.parent_version renewal_parent_version,p.correction_due_date,p.correction_requirements requirements_json,p.correction_attachment_required attachment_required_json FROM qua_portal_submission p JOIN qua_supplier_qualification q ON q.id=p.qualification_id AND q.tenant_id=p.tenant_id AND q.supplier_id=p.supplier_id LEFT JOIN qua_portal_correction c ON c.qualification_id=p.qualification_id AND c.tenant_id=p.tenant_id LEFT JOIN qua_portal_renewal r ON r.qualification_id=p.qualification_id AND r.tenant_id=p.tenant_id WHERE p.tenant_id=#{tenantId} AND p.supplier_id=#{supplierId} AND p.qualification_id=#{id} FOR UPDATE")
    PortalCertificateSubmissionModels.CorrectionSource lockCorrectionSource(long tenantId,long supplierId,long id);
    @Select("SELECT COUNT(*) FROM qua_portal_correction WHERE tenant_id=#{tenantId} AND predecessor_id=#{id}") int correctionChildren(long tenantId,long id);
    @Insert("INSERT INTO qua_portal_correction(qualification_id,tenant_id,supplier_id,predecessor_id,predecessor_version,root_id,round_no,correction_note,source_due_date,source_requirements,correction_responses,late_flag,source_attachment_required) VALUES(#{id},#{tenantId},#{supplierId},#{previous},#{version},#{root},#{round},#{note},#{dueDate},#{requirements},#{responses},#{late},#{attachmentRequired})")
    int insertCorrection(long id,long tenantId,long supplierId,long previous,int version,long root,int round,String note,java.time.LocalDate dueDate,String requirements,String responses,boolean late,String attachmentRequired);
    @Insert("INSERT INTO qua_portal_upload_use(upload_id,tenant_id,supplier_id,qualification_id,usage_kind) VALUES(#{uploadId},#{tenantId},#{supplierId},#{id},#{kind})") int consumeUpload(long uploadId,long tenantId,long supplierId,long id,String kind);
    @Insert("INSERT INTO qua_correction_attachment(id,tenant_id,supplier_id,qualification_id,requirement_index,upload_id,file_id,file_name) VALUES(#{attachmentId},#{tenantId},#{supplierId},#{id},#{index},#{uploadId},#{fileId},#{name})") int insertAttachment(long attachmentId,long tenantId,long supplierId,long id,int index,long uploadId,long fileId,String name);
    String FROM=" FROM qua_portal_submission p JOIN qua_supplier_qualification q ON q.id=p.qualification_id AND q.tenant_id=p.tenant_id AND q.supplier_id=p.supplier_id JOIN qua_qualification_type t ON t.id=q.qualification_type_id AND t.tenant_id=p.tenant_id LEFT JOIN qua_portal_renewal r ON r.qualification_id=q.id AND r.tenant_id=p.tenant_id AND r.supplier_id=p.supplier_id LEFT JOIN qua_supplier_qualification old ON old.id=r.parent_id AND old.tenant_id=p.tenant_id AND old.supplier_id=p.supplier_id LEFT JOIN qua_portal_correction c ON c.qualification_id=p.qualification_id AND c.tenant_id=p.tenant_id AND c.supplier_id=p.supplier_id LEFT JOIN qua_portal_correction child ON child.predecessor_id=p.qualification_id AND child.tenant_id=p.tenant_id AND child.supplier_id=p.supplier_id LEFT JOIN qua_portal_withdrawal w ON w.qualification_id=p.qualification_id AND w.tenant_id=p.tenant_id WHERE p.tenant_id=#{tenantId} AND p.supplier_id=#{supplierId}";
    String SELECT="SELECT CAST(q.id AS CHAR) id,p.request_key,t.type_name,q.certificate_no,q.status,p.file_name,p.created_at submitted_at,CAST(old.id AS CHAR) parent_qualification_id,old.certificate_no parent_certificate_no,p.public_review_comment,p.public_reviewed_at reviewed_at,CAST(q.qualification_type_id AS CHAR) type_id,q.issuing_authority,q.issue_date,q.effective_date,q.expiry_date,q.permanent_flag permanent,q.version,CAST(c.predecessor_id AS CHAR) correction_of_id,CAST(COALESCE(c.root_id,q.id) AS CHAR) correction_root_id,COALESCE(c.round_no,0) correction_round,c.correction_note,CAST(child.qualification_id AS CHAR) correction_child_id,p.correction_due_date,p.correction_requirements correction_requirements_json,c.source_due_date source_correction_due_date,c.source_requirements source_requirements_json,c.correction_responses correction_responses_json,COALESCE(c.late_flag,0) late_correction,p.correction_attachment_required attachment_required_json,c.source_attachment_required source_attachment_required_json,(q.status='DRAFT' AND p.account_id=#{accountId}) withdrawable,w.reason withdrawal_reason,w.withdrawn_at";
    @Select(SELECT+FROM+" AND q.id=#{id}") PortalCertificateSubmissionModels.View find(long tenantId,long supplierId,long id,long accountId);
    @Select("SELECT COUNT(*)"+FROM) long count(long tenantId,long supplierId);
    @Select(SELECT+FROM+" ORDER BY p.created_at DESC,p.qualification_id DESC LIMIT #{size} OFFSET #{offset}") List<PortalCertificateSubmissionModels.View> list(long tenantId,long supplierId,long accountId,int offset,int size);
}
